/**
 * Contacts generated by a fiche technique for its importer (owner,
 * 2026-11-19): the « Demande de devis » form and the counters of taps on
 * Appel, WhatsApp, Devis and Comparer, shown per importer in the admin so
 * the owner can show a subscribed importer what the site brings him.
 *
 *   POST /api/tech-specs/:id/quote   { first_name, last_name, phone, email, consent, website (trap), page_url, session_id }
 *   POST /api/tech-specs/:id/lead    { kind: call | whatsapp | compare, session_id }
 *   GET  /api/admin/leads/summary?days=30
 *   GET  /api/admin/leads/importers/:id?days=30
 *   GET  /api/admin/leads/importers/:id/quotes.csv?days=30
 *
 * Tables: migrations/040_tech_spec_leads.sql, also created here at first
 * use (the server may run without that migration).
 */
const { query } = require('../config/database');
const { isBotRequest } = require('../utils/botDetection');
const { subscribedSql } = require('../utils/importerSubscription');
const { sendQuoteRequestEmails } = require('../services/mailer');
const logger = require('../utils/logger');

const FRONTEND_URL = process.env.FRONTEND_URL || 'https://www.moto-scoot.tn';
const TAP_KINDS = new Set(['call', 'whatsapp', 'compare']);
/** One person tapping 5 times counts once: same session, fiche and kind within this window. */
const DEDUPE_MINUTES = 30;
/** Quotes accepted per IP address and hour (no global rate limiter on this API). */
const QUOTES_PER_IP_HOUR = 5;

let tablesEnsured = false;
async function ensureLeadTables() {
  if (tablesEnsured) return;
  await query(`CREATE TABLE IF NOT EXISTS quote_requests (
    id BIGSERIAL PRIMARY KEY,
    tech_spec_id UUID REFERENCES tech_specs(id) ON DELETE SET NULL,
    importer_id UUID REFERENCES importers(id) ON DELETE SET NULL,
    brand VARCHAR(100), model VARCHAR(150),
    first_name VARCHAR(80) NOT NULL, last_name VARCHAR(80) NOT NULL,
    phone VARCHAR(40) NOT NULL, email VARCHAR(160) NOT NULL,
    consent BOOLEAN NOT NULL DEFAULT FALSE, page_url TEXT, ip_address VARCHAR(64),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);
  await query('CREATE INDEX IF NOT EXISTS idx_quote_requests_importer ON quote_requests (importer_id, created_at DESC)');
  await query(`CREATE TABLE IF NOT EXISTS lead_events (
    id BIGSERIAL PRIMARY KEY,
    tech_spec_id UUID REFERENCES tech_specs(id) ON DELETE SET NULL,
    importer_id UUID REFERENCES importers(id) ON DELETE SET NULL,
    kind VARCHAR(16) NOT NULL CHECK (kind IN ('call', 'whatsapp', 'quote', 'compare')),
    session_id VARCHAR(64),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);
  await query('CREATE INDEX IF NOT EXISTS idx_lead_events_importer ON lead_events (importer_id, created_at DESC)');
  tablesEnsured = true;
}

const clean = (v, max) => String(v ?? '').replace(/\s+/g, ' ').trim().slice(0, max);
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
/** Tunisian or international number: 8+ digits once spaces, dots, dashes and brackets are gone. */
const phoneOk = (p) => /^\+?[0-9]{8,15}$/.test(p.replace(/[\s().-]/g, ''));
const clientIp = (req) => (req.ip || String(req.headers['x-forwarded-for'] || '')).split(',')[0].trim() || null;
const sessionOf = (body) => clean(body?.session_id, 64) || null;

/** Checks the form; returns { error } or the cleaned fields. */
function validateQuote(body = {}) {
  const f = {
    first_name: clean(body.first_name, 80),
    last_name: clean(body.last_name, 80),
    phone: clean(body.phone, 40),
    email: clean(body.email, 160).toLowerCase(),
  };
  if (!f.first_name || !f.last_name) return { error: 'Nom et prénom obligatoires' };
  if (!phoneOk(f.phone)) return { error: 'Numéro de téléphone invalide' };
  if (!EMAIL_RE.test(f.email)) return { error: 'Adresse e-mail invalide' };
  if (body.consent !== true) return { error: 'Merci d’accepter l’utilisation de vos coordonnées' };
  return f;
}

/** The fiche, its importer, and whether that importer is subscribed today. */
async function specWithImporter(id) {
  const { rows } = await query(
    `SELECT t.id, t.brand, t.model, t.slug, t.image, t.price_new, t.importer_id,
            i.name AS importer_name, i.email AS importer_email,
            ${subscribedSql('i')} AS subscribed
       FROM tech_specs t LEFT JOIN importers i ON i.id = t.importer_id
      WHERE t.id = $1`,
    [id],
  );
  return rows[0] || null;
}

async function requestQuote(req, res, next) {
  try {
    // Trap field, hidden from people: a robot fills it. Answer as if it worked.
    if (clean(req.body?.website, 200)) return res.status(201).json({ success: true });
    const f = validateQuote(req.body);
    if (f.error) return res.status(400).json({ error: f.error });

    await ensureLeadTables();
    const spec = await specWithImporter(req.params.id);
    if (!spec) return res.status(404).json({ error: 'Fiche introuvable' });
    if (!spec.importer_id || !spec.subscribed) {
      return res.status(409).json({ error: 'Les demandes de devis ne sont pas ouvertes pour ce modèle' });
    }

    const ip = clientIp(req);
    const recent = await query(
      `SELECT
         COUNT(*) FILTER (WHERE ip_address = $1 AND created_at > NOW() - INTERVAL '1 hour') AS by_ip,
         COUNT(*) FILTER (WHERE tech_spec_id = $2 AND (email = $3 OR phone = $4) AND created_at > NOW() - INTERVAL '1 hour') AS same
       FROM quote_requests`,
      [ip, spec.id, f.email, f.phone],
    );
    if (Number(recent.rows[0].same) > 0) return res.json({ success: true, deduped: true, importer: spec.importer_name });
    if (Number(recent.rows[0].by_ip) >= QUOTES_PER_IP_HOUR) {
      return res.status(429).json({ error: 'Trop de demandes envoyées. Réessayez dans une heure.' });
    }

    const pageUrl = `${FRONTEND_URL}/fiche-technique/${spec.slug || spec.id}`;
    const ins = await query(
      `INSERT INTO quote_requests (tech_spec_id, importer_id, brand, model, first_name, last_name, phone, email, consent, page_url, ip_address)
       VALUES ($1,$2,$3,$4,$5,$6,$7,$8,TRUE,$9,$10) RETURNING id`,
      [spec.id, spec.importer_id, spec.brand, spec.model, f.first_name, f.last_name, f.phone, f.email, pageUrl, ip],
    );
    query(
      `INSERT INTO lead_events (tech_spec_id, importer_id, kind, session_id) VALUES ($1,$2,'quote',$3)`,
      [spec.id, spec.importer_id, sessionOf(req.body)],
    ).catch((e) => logger.warn('[quote] event failed:', e.message));

    // The request is stored: the e-mails go out without holding the answer.
    sendQuoteRequestEmails({
      importerName: spec.importer_name, importerEmail: spec.importer_email,
      brand: spec.brand, model: spec.model, priceLabel: spec.price_new ? `${spec.price_new}` : '',
      imageUrl: spec.image, pageUrl,
      firstName: f.first_name, lastName: f.last_name, phone: f.phone, email: f.email,
    }).then((sent) => logger.info?.('[quote] mails', sent))
      .catch((e) => logger.warn('[quote] mails failed:', e.message));

    res.status(201).json({ success: true, id: ins.rows[0].id, importer: spec.importer_name });
  } catch (err) { next(err); }
}

async function trackLead(req, res, next) {
  try {
    const kind = clean(req.body?.kind, 16);
    if (!TAP_KINDS.has(kind)) return res.status(400).json({ error: 'kind must be call, whatsapp or compare' });
    if (isBotRequest(req)) return res.status(202).json({ skipped: 'bot' });
    await ensureLeadTables();
    const spec = await specWithImporter(req.params.id);
    if (!spec) return res.status(202).json({ skipped: 'unknown' });
    const session = sessionOf(req.body);
    if (session) {
      const dup = await query(
        `SELECT 1 FROM lead_events WHERE session_id = $1 AND tech_spec_id = $2 AND kind = $3
            AND created_at > NOW() - make_interval(mins => $4) LIMIT 1`,
        [session, spec.id, kind, DEDUPE_MINUTES],
      );
      if (dup.rows.length) return res.status(202).json({ skipped: 'repeat' });
    }
    await query(
      'INSERT INTO lead_events (tech_spec_id, importer_id, kind, session_id) VALUES ($1,$2,$3,$4)',
      [spec.id, spec.importer_id, kind, session],
    );
    res.status(201).json({ success: true });
  } catch (err) { next(err); }
}

const periodDays = (req) => Math.min(Math.max(parseInt(req.query.days, 10) || 30, 1), 366);

/** Every importer with its counters over the period (subscribed first). */
async function adminSummary(req, res, next) {
  try {
    await ensureLeadTables();
    const days = periodDays(req);
    const { rows } = await query(
      `SELECT i.id, i.name, i.phone, i.email, i.whatsapp,
              (to_jsonb(i)->>'subscription_until') AS subscription_until,
              ${subscribedSql('i')} AS subscribed,
              COUNT(e.id) FILTER (WHERE e.kind = 'call')     AS calls,
              COUNT(e.id) FILTER (WHERE e.kind = 'whatsapp') AS whatsapp_taps,
              COUNT(e.id) FILTER (WHERE e.kind = 'quote')    AS quotes,
              COUNT(e.id) FILTER (WHERE e.kind = 'compare')  AS compares
         FROM importers i
         LEFT JOIN lead_events e ON e.importer_id = i.id AND e.created_at > NOW() - make_interval(days => $1)
        GROUP BY i.id
        ORDER BY subscribed DESC, (COUNT(e.id)) DESC, i.name`,
      [days],
    );
    res.json({ days, importers: rows.map(numberCounts) });
  } catch (err) { next(err); }
}

function numberCounts(r) {
  const out = { ...r };
  for (const k of ['calls', 'whatsapp_taps', 'quotes', 'compares']) out[k] = Number(r[k] || 0);
  return out;
}

/** One importer: totals, by model, by day, latest quote requests. */
async function adminImporter(req, res, next) {
  try {
    await ensureLeadTables();
    const days = periodDays(req);
    const id = req.params.id;
    const [imp, byModel, byDay, quotes] = await Promise.all([
      query(`SELECT i.id, i.name, i.phone, i.email, i.whatsapp,
                    (to_jsonb(i)->>'subscription_until') AS subscription_until, ${subscribedSql('i')} AS subscribed
               FROM importers i WHERE i.id = $1`, [id]),
      query(`SELECT t.id, t.brand, t.model,
                    COUNT(*) FILTER (WHERE e.kind = 'call')     AS calls,
                    COUNT(*) FILTER (WHERE e.kind = 'whatsapp') AS whatsapp_taps,
                    COUNT(*) FILTER (WHERE e.kind = 'quote')    AS quotes,
                    COUNT(*) FILTER (WHERE e.kind = 'compare')  AS compares
               FROM lead_events e JOIN tech_specs t ON t.id = e.tech_spec_id
              WHERE e.importer_id = $1 AND e.created_at > NOW() - make_interval(days => $2)
              GROUP BY t.id ORDER BY COUNT(*) DESC, t.brand, t.model`, [id, days]),
      query(`SELECT to_char(date_trunc('day', created_at), 'YYYY-MM-DD') AS day, kind, COUNT(*) AS n
               FROM lead_events WHERE importer_id = $1 AND created_at > NOW() - make_interval(days => $2)
              GROUP BY 1, 2 ORDER BY 1`, [id, days]),
      query(`SELECT id, brand, model, first_name, last_name, phone, email, created_at
               FROM quote_requests WHERE importer_id = $1 AND created_at > NOW() - make_interval(days => $2)
              ORDER BY created_at DESC LIMIT 200`, [id, days]),
    ]);
    if (!imp.rows.length) return res.status(404).json({ error: 'Importateur introuvable' });
    const models = byModel.rows.map(numberCounts);
    const totals = models.reduce((t, m) => ({
      calls: t.calls + m.calls, whatsapp_taps: t.whatsapp_taps + m.whatsapp_taps,
      quotes: t.quotes + m.quotes, compares: t.compares + m.compares,
    }), { calls: 0, whatsapp_taps: 0, quotes: 0, compares: 0 });
    res.json({ days, importer: imp.rows[0], totals, models, daily: byDay.rows.map((r) => ({ ...r, n: Number(r.n) })), quotes: quotes.rows });
  } catch (err) { next(err); }
}

const csvCell = (v) => {
  const s = v == null ? '' : String(v);
  // « =cmd » etc. would run as a formula in Excel: prefix with an apostrophe.
  const safe = /^[=+\-@\t\r]/.test(s) ? `'${s}` : s;
  return /[";\n]/.test(safe) ? `"${safe.replace(/"/g, '""')}"` : safe;
};

/** Quote requests of one importer as CSV (« ; » separator, opens in Excel FR). */
async function adminQuotesCsv(req, res, next) {
  try {
    await ensureLeadTables();
    const days = periodDays(req);
    const { rows } = await query(
      `SELECT created_at, brand, model, first_name, last_name, phone, email, page_url
         FROM quote_requests WHERE importer_id = $1 AND created_at > NOW() - make_interval(days => $2)
        ORDER BY created_at DESC`,
      [req.params.id, days],
    );
    const head = ['Date', 'Marque', 'Modèle', 'Prénom', 'Nom', 'Téléphone', 'E-mail', 'Fiche'];
    const lines = rows.map((r) => [new Date(r.created_at).toISOString().slice(0, 16).replace('T', ' '), r.brand, r.model, r.first_name, r.last_name, r.phone, r.email, r.page_url].map(csvCell).join(';'));
    res.setHeader('Content-Type', 'text/csv; charset=utf-8');
    res.setHeader('Content-Disposition', `attachment; filename="demandes-devis-${days}j.csv"`);
    res.send(`﻿${[head.join(';'), ...lines].join('\n')}\n`);
  } catch (err) { next(err); }
}

module.exports = { requestQuote, trackLead, adminSummary, adminImporter, adminQuotesCsv, _internals: { validateQuote, csvCell, phoneOk } };
